mapper.select:
SELECT l.id, l.batch_id, l.business_type, b.batch_no, b.original_file_name, l.shipment_id, l.order_sn, l.source_rows, l.source_row_count, l.status, l.error_stage, l.error_code, l.error_message, l.exception_type, l.stack_trace, l.request_id, l.lingxing_response_time, l.attempt_count, l.request_body, l.response_body, l.source_data, l.operator, l.upload_time, l.start_time, l.success_time, l.failed_time, l.duration_ms, l.create_time, l.update_time FROM customs_shipment_fee_import_log l INNER JOIN customs_shipment_fee_import_batch b ON b.id = l.batch_id
AND l.business_type = #{businessType}
AND b.batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND ( l.order_sn LIKE CONCAT('%', #{orderSn}, '%') OR l.shipment_id LIKE CONCAT('%', #{orderSn}, '%') )
AND l.status = #{status}
AND l.operator LIKE CONCAT('%', #{operator}, '%')
AND l.upload_time >= #{beginTime}
AND l.upload_time <= #{endTime}
ORDER BY l.id DESC
